const fetch = require('node-fetch');

// Configuration
const CROSSMINT_API_KEY = process.env.CROSSMINT_API_KEY || '';
const MINT_URL = 'https://staging.crossmint.com/api/2022-06-09/collections/default/nfts';
const POLL_INTERVAL_MS = 2000;
const MAX_POLL_ATTEMPTS = 5;

async function mintNFT() {
  const result = {
    actionId: 'mock-action-id',
    final_status: 'unknown',
    poll_attempts: 0,
    mint_chain: 'polygon-amoy',
    error: null
  };

  try {
    if (!CROSSMINT_API_KEY) {
      result.error = 'CROSSMINT_API_KEY environment variable not set';
      return result;
    }

    // Step 1: Initiate mint
    console.log('Initiating NFT mint...');
    const mintResponse = await fetch(MINT_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-API-KEY': CROSSMINT_API_KEY
      },
      body: JSON.stringify({
        recipient: 'email:demo@example.com:polygon-amoy',
        metadata: {
          name: 'Poll Test NFT',
          description: 'Testing async polling',
          image: 'https://example.com/poll.png'
        }
      })
    });

    if (!mintResponse.ok) {
      const errorText = await mintResponse.text();
      result.error = `Mint request failed with status ${mintResponse.status}: ${errorText}`;
      return result;
    }

    const mintData = await mintResponse.json();
    result.actionId = mintData.actionId || mintData.id;

    if (!result.actionId) {
      result.error = 'No actionId found in mint response';
      return result;
    }

    console.log(`Mint initiated with actionId: ${result.actionId}`);

    // Step 2 & 3: Poll for action status
    let currentStatus = 'pending';
    let attempts = 0;

    while (attempts < MAX_POLL_ATTEMPTS && currentStatus === 'pending') {
      attempts++;
      result.poll_attempts = attempts;

      console.log(`Poll attempt ${attempts}/${MAX_POLL_ATTEMPTS}...`);

      // Wait before polling (except first attempt)
      if (attempts > 1) {
        await new Promise(resolve => setTimeout(resolve, POLL_INTERVAL_MS));
      }

      try {
        const pollUrl = `https://staging.crossmint.com/api/2022-06-09/actions/${result.actionId}`;
        const pollResponse = await fetch(pollUrl, {
          method: 'GET',
          headers: {
            'X-API-KEY': CROSSMINT_API_KEY
          }
        });

        if (!pollResponse.ok) {
          const errorText = await pollResponse.text();
          result.error = `Poll request failed with status ${pollResponse.status}: ${errorText}`;
          return result;
        }

        const pollData = await pollResponse.json();
        currentStatus = pollData.status || 'unknown';
        console.log(`Current status: ${currentStatus}`);

      } catch (pollError) {
        result.error = `Poll attempt ${attempts} failed: ${pollError.message}`;
        return result;
      }
    }

    result.final_status = currentStatus;

  } catch (error) {
    result.error = error.message;
  }

  return result;
}

// Main execution
(async () => {
  try {
    const result = await mintNFT();

    // Step 4: Write result to JSON file
    const fs = require('fs');
    const resultPath = '/home/user/poll_result.json';
    fs.writeFileSync(resultPath, JSON.stringify(result, null, 2));

    console.log(`\nResult written to ${resultPath}`);
    console.log(JSON.stringify(result, null, 2));

  } catch (error) {
    console.error('Fatal error:', error);
    process.exit(1);
  }
})();

